parameters.jsCode:
// Node 12: Parse engineer approval from Slack Form + AI Agent recommendation
// Priority:
// 1) data["CF account"] (email typed by engineer) => OVERRIDDEN (highest priority)
// 2) data["USE?"] commands:
//    - ok/yes/approved => APPROVED => use AI selected account
//    - use <id> / pick <id> => OVERRIDDEN => selected_account_id = <id>
//    - redo: <hint> => REDO
// 3) otherwise INVALID
//
// IMPORTANT: AI Agent output is read reliably via $items("AI Agent")[0].json.output

function normalize(s) {
  return String(s ?? '').trim();
}

function upper(s) {
  return normalize(s).toUpperCase();
}

function isEmail(s) {
  const t = normalize(s);
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(t);
}

// Pull current item (Slack send-and-wait result)
const item = $input.first().json;

// Slack form fields
const data = item.data || {};
const cfAccountRaw = normalize(data['CF account']); // engineer typed email here
const useRaw = normalize(data['USE?']);             // ok / use 12 / redo: ...

// Pull AI Agent output reliably (node name must match exactly "AI Agent")
let aiOut = {};
try {
  aiOut = $items('AI Agent')[0]?.json?.output ?? {};
} catch (e) {
  aiOut = {};
}

const aiSelectedId = aiOut.selected_account_id ?? null;
const aiSelectedName = aiOut.selected_account_name ?? null;
const aiSelectedEmail = aiOut.selected_account_email ?? null;

// Helpers for numeric check
const isInt = (v) => Number.isInteger(typeof v === 'string' ? Number(v) : v);

// 1) Highest priority: engineer typed CF account email
if (cfAccountRaw && isEmail(cfAccountRaw)) {
  return [{
    ...item,
    approval_status: 'OVERRIDDEN',
    approval_result: 'corrected',
    engineer_raw_reply: JSON.stringify(data),

    // override by email (ID can be resolved later via DM lookup by email)
    selected_account_email: cfAccountRaw,
    selected_account_id: null,
    selected_account_name: null,

    // keep AI proposal for reference
    proposed_account_id: isInt(aiSelectedId) ? Number(aiSelectedId) : null,
    proposed_account_name: aiSelectedName ?? null,
    proposed_account_email: aiSelectedEmail ?? null,

    redo_hint: null,
    override_source: 'engineer_email',
  }];
}

// 2) Parse USE? command
const useUpper = upper(useRaw);

// REDO: ....
let m = useRaw.match(/^REDO\s*:?\s*(.+)$/i);
if (m) {
  return [{
    ...item,
    approval_status: 'REDO',
    approval_result: 'redo',
    redo_hint: m[1].trim(),
    engineer_raw_reply: JSON.stringify(data),

    proposed_account_id: isInt(aiSelectedId) ? Number(aiSelectedId) : null,
    proposed_account_name: aiSelectedName ?? null,
    proposed_account_email: aiSelectedEmail ?? null,

    selected_account_id: null,
    selected_account_name: null,
    selected_account_email: null,
    override_source: 'redo',
  }];
}

// USE 12 / PICK 12
m = useUpper.match(/^(USE|PICK)\s+(\d+)\s*$/);
if (m) {
  return [{
    ...item,
    approval_status: 'OVERRIDDEN',
    approval_result: 'corrected',
    engineer_raw_reply: JSON.stringify(data),

    selected_account_id: Number(m[2]),
    selected_account_name: null,
    selected_account_email: null,

    proposed_account_id: isInt(aiSelectedId) ? Number(aiSelectedId) : null,
    proposed_account_name: aiSelectedName ?? null,
    proposed_account_email: aiSelectedEmail ?? null,

    redo_hint: null,
    override_source: 'engineer_id',
  }];
}

// OK / YES / APPROVED (use AI)
if (useUpper === 'OK' || useUpper === 'YES' || useUpper === 'APPROVED') {
  const finalId = isInt(aiSelectedId) ? Number(aiSelectedId) : null;

  // If AI did not provide selection, mark INVALID to avoid silent nulls
  if (!finalId && !aiSelectedEmail) {
    return [{
      ...item,
      approval_status: 'INVALID',
      approval_result: 'invalid',
      engineer_raw_reply: JSON.stringify(data),
      redo_hint: null,

      proposed_account_id: null,
      proposed_account_name: null,
      proposed_account_email: null,

      selected_account_id: null,
      selected_account_name: null,
      selected_account_email: null,
      override_source: 'ai_missing',
      error_hint: 'Engineer approved OK, but AI Agent output has no selected_account_* fields',
    }];
  }

  return [{
    ...item,
    approval_status: 'APPROVED',
    approval_result: 'approved',
    engineer_raw_reply: JSON.stringify(data),
    redo_hint: null,

    proposed_account_id: finalId,
    proposed_account_name: aiSelectedName ?? null,
    proposed_account_email: aiSelectedEmail ?? null,

    selected_account_id: finalId,
    selected_account_name: aiSelectedName ?? null,
    selected_account_email: aiSelectedEmail ?? null,
    override_source: 'ai_ok',
  }];
}

// tolerate "use12" / "pick12" / "use 12"
m = useUpper.match(/^(USE|PICK)\s*(\d+)\s*$/);
if (m) {
  return [{
    ...item,
    approval_status: 'OVERRIDDEN',
    approval_result: 'corrected',
    engineer_raw_reply: JSON.stringify(data),

    selected_account_id: Number(m[2]),
    selected_account_name: null,
    selected_account_email: null,

    proposed_account_id: isInt(aiSelectedId) ? Number(aiSelectedId) : null,
    proposed_account_name: aiSelectedName ?? null,
    proposed_account_email: aiSelectedEmail ?? null,

    redo_hint: null,
    override_source: 'engineer_id',
  }];
}

// If engineer typed an email in USE?
if (isEmail(useRaw)) {
  return [{
    ...item,
    approval_status: 'OVERRIDDEN',
    approval_result: 'corrected',
    engineer_raw_reply: JSON.stringify(data),

    selected_account_email: useRaw,
    selected_account_id: null,
    selected_account_name: null,

    proposed_account_id: isInt(aiSelectedId) ? Number(aiSelectedId) : null,
    proposed_account_name: aiSelectedName ?? null,
    proposed_account_email: aiSelectedEmail ?? null,

    redo_hint: null,
    override_source: 'engineer_email_in_use',
  }];
}

// INVALID fallback
return [{
  ...item,
  approval_status: 'INVALID',
  approval_result: 'invalid',
  engineer_raw_reply: JSON.stringify(data),
  redo_hint: null,

  proposed_account_id: isInt(aiSelectedId) ? Number(aiSelectedId) : null,
  proposed_account_name: aiSelectedName ?? null,
  proposed_account_email: aiSelectedEmail ?? null,

  selected_account_id: null,
  selected_account_name: null,
  selected_account_email: null,
  override_source: 'invalid',
}];

function first(obj, paths) {
  for (const p of paths) {
    const v = p.split('.').reduce((a, k) => (a && a[k] !== undefined ? a[k] : undefined), obj);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
}
function isEmail(s) {
  const t = String(s ?? '').trim();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(t);
}
function must(v, name) {
  if (v === undefined || v === null || v === '') throw new Error(`WF3 payload: missing required field "${name}"`);
  return v;
}

const item = $input.first().json;

// Required base fields (as per your Data Table)
const domain = must(first(item, ['domain_fqdn', 'domain']), 'domain_fqdn');
const jiraKey = must(first(item, ['jira_issue_key', 'jira_key']), 'jira_issue_key');
const projectCode = must(first(item, ['project_code']), 'project_code');

// CF selection from table
const cfAccountId = first(item, ['cloudflare_account_id_selected']);

// Try proper email column first
let cfAccountEmail = first(item, ['cloudflare_account_email_selected']);

// Fallback: your table currently stores email in "name_selected"
const nameSelected = first(item, ['cloudflare_account_name_selected']);
if (!cfAccountEmail && isEmail(nameSelected)) {
  cfAccountEmail = nameSelected;
}

// Optional: real name (if you ever store it correctly)
const cfAccountName = (!isEmail(nameSelected) ? nameSelected : null);

// Require at least one: id or email
if (!cfAccountId && !cfAccountEmail) {
  throw new Error(
    'WF3 payload: need either cloudflare_account_id_selected or cloudflare_account_email_selected (or email stored in cloudflare_account_name_selected)'
  );
}

const execution_payload = {
  meta: {
    onboarding_id: first(item, ['onboarding_id']) ?? null,
    created_at: new Date().toISOString(),
    source_workflow: 'WF2',
  },
  domain: { fqdn: domain },
  jira: { issue_key: jiraKey },
  project: { project_code: projectCode },

  cloudflare: {
    dns_provider_account_id: cfAccountId ? Number(cfAccountId) : null,
    account_email: cfAccountEmail ?? null,
    account_name: cfAccountName ?? null,
    dm_cloudflare_accounts_ref: first(item, ['dm_cloudflare_accounts']) ?? null,
    actions: {
      add_zone: true,
      fetch_nameservers: true,
      apply_dns_records: true,
      attach_pages_domain: true,
    },
  },

  registrar: {
    provider: 'namecheap',
    account_ref: first(item, ['dm_namecheap_account_ref']) ?? null,
    actions: { set_nameservers: true },
  },

  dns: {
    source: 'dns_templates',
    records: first(item, ['dns_records_json']) ?? [],
  },

  pages: {
    project_name: first(item, ['pages_project_name']) ?? null,
    attach_domain: true,
  },

  approval: {
    result: first(item, ['approval_result']) ?? null,
  },
};

return [{ ...item, execution_payload }];

