// WF2 - DNS resolver (templates in code)
// Output:
// - dns_records_json: array of Cloudflare DNS records
// - cloudflare_settings_json: settings to apply in Cloudflare
// - dns_cluster_target: chosen cluster hostname
// - dns_template_key: debug

function first(obj, paths) {
  for (const p of paths) {
    const v = p.split('.').reduce((a, k) => (a && a[k] !== undefined ? a[k] : undefined), obj);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
}

function normalizeProject(code) {
  const v = String(code ?? '').trim().toUpperCase();
  if (!v) return 'UNKNOWN';
  // allow variants
  if (v === 'PROJECTA' || v === 'PROJECTA' || v === 'PROJECTA ') return 'PROJECTA';
  return v;
}

function isHostnameLike(s) {
  const t = String(s ?? '').trim();
  // quick check for hostnames like cluster-a.example.net
  return /^[a-z0-9-]+(\.[a-z0-9-]+)+$/i.test(t);
}

function mkCname(name, content, proxied = true) {
  return {
    type: 'CNAME',
    name,                // '@', 'www', 'checkout', 'cart', 'reviews', etc.
    content,             // target hostname
    proxied: Boolean(proxied),
    ttl: 1,              // Cloudflare "Auto"
  };
}

const item = $input.first().json;

// Inputs from Data Table row
const projectCodeRaw = first(item, ['project_code']);
const projectCode = normalizeProject(projectCodeRaw);

// Optional: allow override cluster target from some field (add later if you want)
// Examples where you might store it: dm_cluster_target, cluster_target, dns_cluster_target, notes, jira_description etc.
let clusterTarget = first(item, [
  'dns_cluster_target',
  'cluster_target',
  'dm_cluster_target',
  'row.dns_cluster_target',
  'data.dns_cluster_target',
]);

// If none provided, default:
if (!clusterTarget || !isHostnameLike(clusterTarget)) {
  clusterTarget = 'cluster-a.example.net';
}

// Special note in your screenshot: "ProjectB, ProjectC, ProjectD - уточнити точну адресу кластера"
// We'll implement that as: default to sc-... but flag "needs_cluster_confirmation" for these projects
const needsClusterConfirmation = ['PROJECTB', 'PROJECTC', 'PROJECTD'].includes(projectCode);

// constants from your docs
const CART_TARGET_ELB = 'lb-1.example.net';

// 1) Always/base records
const records = [];
records.push(mkCname('@', clusterTarget, true)); // @ -> cluster
records.push(mkCname('www', '@', true));         // www -> @

// 2) Conditional records
// Used checkout only PROJECTE
if (projectCode === 'PROJECTE') {
  records.push(mkCname('checkout', clusterTarget, true));
}

// Used reviews only ProjectA
if (projectCode === 'PROJECTA') {
  records.push(mkCname('reviews', clusterTarget, true));
}

// Used cart (all other checkout and reviews)
if (projectCode !== 'PROJECTE' && projectCode !== 'PROJECTA') {
  records.push(mkCname('cart', CART_TARGET_ELB, true));
}

// Cloudflare settings from your screenshot (SSL/TLS)
const cloudflare_settings_json = {
  always_use_https: true,
  min_tls_version: '1.2',
  ssl_mode: 'full',
};

// Debug/template metadata
const dns_template_key = `${projectCode}::cluster=${clusterTarget}`;

return [{
  ...item,
  dns_records_json: records,
  cloudflare_settings_json,
  dns_cluster_target: clusterTarget,
  dns_template_key,
  needs_cluster_confirmation: needsClusterConfirmation,
}];

const j = $input.first().json;

return [{
  ...j,
  domain_fqdn: j.domain_fqdn ?? j.domain ?? j.domain_raw ?? null,
  jira_issue_key: j.jira_issue_key ?? j.jira_key ?? null,
  onboarding_id: j.onboarding_id ?? null,
  project_code: j.project_code ?? null,
}];

const base = $input.first().json;
const ai = $items("AI Agent")[0]?.json?.output ?? {};

const domain = base.domain_fqdn ?? base.domain ?? base.domain_raw ?? '';
const jira = base.jira_issue_key ?? '';

const text =
`*🚀 Domain Onboarding Request*
*Domain:* \`${domain}\`
*Jira:* <https://company.atlassian.net/browse/${jira}|${jira}>

*🤖 AI Recommendation:*
Account: *${ai.selected_account_name}* (ID: ${ai.selected_account_id})
Email: ${ai.selected_account_email}

Confidence: ${ai.confidence}
Evidence: ${ai.reason}

---
*How to respond:*
• Fill \`CF account\` (email) to override
• Or use \`USE?\`: ok / use 12 / redo: ...`;

return [{ ...base, slack_message_text: text }];
